let db: Database.Database;
let databaseMode: 'uninitialized' | 'production' | 'isolated_test' =
  'uninitialized';

const DATABASE_BUSY_TIMEOUT_MS = 15_000;
const DATABASE_WAL_AUTOCHECKPOINT_PAGES = 1_000;
const DATABASE_JOURNAL_SIZE_LIMIT_BYTES = 64 * 1024 * 1024;

function openDatabaseConnection(dbPath: string): Database.Database {
  const database = new Database(dbPath, {
    timeout: DATABASE_BUSY_TIMEOUT_MS,
  });
  database.pragma(`busy_timeout = ${DATABASE_BUSY_TIMEOUT_MS}`);
  database.pragma('foreign_keys = ON');
  if (dbPath !== ':memory:') {
    // Operator diagnostics and the long-running assistant legitimately share
    // this database. WAL lets readers proceed during writes; the bounded busy
    // timeout makes short writer overlap retry instead of failing immediately.
    database.pragma('journal_mode = WAL');
    database.pragma('synchronous = NORMAL');
    // Keep the normal checkpoint trigger explicit and bound retained WAL file
    // capacity after a successful reset. journal_size_limit does not cap an
    // active transaction; it only prevents an old high-water allocation from
    // consuming disk indefinitely after SQLite can safely reset the WAL.
    database.pragma(
      `wal_autocheckpoint = ${DATABASE_WAL_AUTOCHECKPOINT_PAGES}`,
    );
    database.pragma(
      `journal_size_limit = ${DATABASE_JOURNAL_SIZE_LIMIT_BYTES}`,
    );
  }
  return database;
}

export function isDatabaseInitialized(): boolean {
  return Boolean(db && db.open);
}

export function isIsolatedTestDatabase(): boolean {
  return isDatabaseInitialized() && databaseMode === 'isolated_test';
}

/** @internal - exposes connection policy for disposable-database tests. */
export function _getDatabaseConnectionPolicy(): {
  busyTimeoutMs: number;
  journalMode: string;
  synchronous: number;
  walAutoCheckpointPages: number;
  journalSizeLimitBytes: number;
} {
  if (!isDatabaseInitialized()) {
    throw new Error('Database is not initialized.');
  }
  return {
    busyTimeoutMs: Number(db.pragma('busy_timeout', { simple: true })),
    journalMode: String(db.pragma('journal_mode', { simple: true })),
    synchronous: Number(db.pragma('synchronous', { simple: true })),
    walAutoCheckpointPages: Number(
      db.pragma('wal_autocheckpoint', { simple: true }),
    ),
    journalSizeLimitBytes: Number(
      db.pragma('journal_size_limit', { simple: true }),
    ),
  };
}

function redactStoredCognitiveMetadata(value: string, limit = 12000): string {
  return redactCouncilText(value || '', limit);
}

function sanitizeStoredStructuredJson(
  value: string,
  field: string,
  limit = 12000,
): string {
  let parsed: unknown;
  try {
    parsed = JSON.parse(value);
  } catch (error) {
    throw new Error(`${field} must contain valid JSON.`, { cause: error });
  }
  const visit = (input: unknown, depth: number): unknown => {
    if (depth > 16) throw new Error(`${field} exceeds the maximum JSON depth.`);
    if (Array.isArray(input)) {
      if (input.length > 500) {
        throw new Error(`${field} exceeds the maximum array size.`);
      }
      return input.map((child) => visit(child, depth + 1));
    }
    if (input && typeof input === 'object') {
      const entries = Object.entries(input as Record<string, unknown>);
      if (entries.length > 500) {
        throw new Error(`${field} exceeds the maximum object size.`);
      }
      return Object.fromEntries(
        entries
          .sort(([left], [right]) => left.localeCompare(right))
          .map(([key, child]) => [
            key.slice(0, 180),
            isSensitiveName(key) &&
            !/(?:requirements?|stored|redacted|state|status|ids?)$/i.test(key)
              ? '[REDACTED_SECRET]'
              : visit(child, depth + 1),
          ]),
      );
    }
    if (typeof input === 'string') return redactCouncilText(input, 2400);
    if (
      input === null ||
      typeof input === 'number' ||
      typeof input === 'boolean'
    ) {
      return input;
    }
    return null;
  };
  const serialized = JSON.stringify(visit(parsed, 0));
  if (Buffer.byteLength(serialized, 'utf8') > limit) {
    throw new Error(`${field} exceeds the ${limit}-byte storage limit.`);
  }
  return serialized;
}

function sanitizeStoredIdArrayJson(value: string, limit = 12000): string {
  try {
    const parsed = JSON.parse(value || '[]');
    if (!Array.isArray(parsed)) {
      return JSON.stringify(['__invalid_json_shape__']);
    }
    const ids = parsed
      .filter((item): item is string => typeof item === 'string')
      .map((item) => item.replace(/[^A-Za-z0-9:_-]+/g, '_').slice(0, 220))
      .filter(Boolean);
    if (ids.length !== parsed.length) {
      ids.push('__invalid_array_item__');
    }
    const json = JSON.stringify(ids);
    if (json.length <= limit) return json;
    const kept: string[] = [];
    for (const id of ids) {
      const next = JSON.stringify([...kept, id, '__truncated__']);
      if (next.length > limit) break;
      kept.push(id);
    }
    return JSON.stringify([...kept, '__truncated__']);
  } catch {
    return JSON.stringify(['__invalid_json__']);
  }
}

function sanitizeStoredJsonObject(value: string, limit: number): string {
  try {
    const parsed = JSON.parse(value || '{}');
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return '{"invalid":true,"reason":"shape"}';
    }
    const redacted = redactStoredCognitiveMetadata(
      JSON.stringify(parsed),
      limit,
    );
    const reparsed = JSON.parse(redacted);
    if (!reparsed || typeof reparsed !== 'object' || Array.isArray(reparsed)) {
      return '{"invalid":true,"reason":"redaction"}';
    }
    return redacted;
  } catch {
    return '{"invalid":true,"reason":"parse"}';
  }
}

