/**
 * Store chat metadata only (no message content).
 * Used for all chats to enable group discovery without storing sensitive content.
 */
function normalizeChatNameCandidate(value: string | null | undefined): string {
  return (value || '').trim();
}

function isPlaceholderChatName(
  chatJid: string,
  name: string | null | undefined,
): boolean {
  const normalizedName = normalizeChatNameCandidate(name);
  if (!normalizedName) return true;
  const jidSansPrefix = chatJid.replace(/^bb:/i, '');
  if (normalizedName === chatJid || normalizedName === jidSansPrefix) {
    return true;
  }
  return /^(?:bb:)?(?:iMessage|SMS|RCS):[+-];(?:chat[0-9]+|[^ ]+@[^ ]+|\+?\d+)$/i.test(
    normalizedName,
  );
}

export function storeChatMetadata(
  chatJid: string,
  timestamp: string,
  name?: string,
  channel?: string,
  isGroup?: boolean,
): void {
  const ch = channel ?? null;
  const blueBubblesGroupGuid =
    chatJid.startsWith('bb:') && /^bb:[^;]+;\+;/.test(chatJid);
  const group = blueBubblesGroupGuid
    ? 1
    : isGroup === undefined
      ? null
      : isGroup
        ? 1
        : 0;
  const normalizedName = normalizeChatNameCandidate(name);
  const safeName =
    normalizedName && !isPlaceholderChatName(chatJid, normalizedName)
      ? normalizedName
      : null;

  if (safeName) {
    // Update with name, preserving existing timestamp if newer
    db.prepare(
      `
      INSERT INTO chats (jid, name, last_message_time, channel, is_group) VALUES (?, ?, ?, ?, ?)
      ON CONFLICT(jid) DO UPDATE SET
        name = excluded.name,
        last_message_time = MAX(last_message_time, excluded.last_message_time),
        channel = COALESCE(excluded.channel, channel),
        is_group = COALESCE(excluded.is_group, is_group)
    `,
    ).run(chatJid, safeName, timestamp, ch, group);
  } else {
    // Update timestamp only, preserve existing name if any
    db.prepare(
      `
      INSERT INTO chats (jid, name, last_message_time, channel, is_group) VALUES (?, ?, ?, ?, ?)
      ON CONFLICT(jid) DO UPDATE SET
        last_message_time = MAX(last_message_time, excluded.last_message_time),
        channel = COALESCE(excluded.channel, channel),
        is_group = COALESCE(excluded.is_group, is_group)
    `,
    ).run(chatJid, chatJid, timestamp, ch, group);
  }
}

/**
 * Update chat name without changing timestamp for existing chats.
 * New chats get the current time as their initial timestamp.
 * Used during group metadata sync.
 */
export function updateChatName(chatJid: string, name: string): void {
  if (isPlaceholderChatName(chatJid, name)) {
    return;
  }
  db.prepare(
    `
    INSERT INTO chats (jid, name, last_message_time) VALUES (?, ?, ?)
    ON CONFLICT(jid) DO UPDATE SET name = excluded.name
  `,
  ).run(chatJid, name, new Date().toISOString());
}

export interface ChatInfo {
  jid: string;
  name: string;
  last_message_time: string;
  channel: string;
  is_group: number;
}

/**
 * Get all known chats, ordered by most recent activity.
 */
export function getAllChats(): ChatInfo[] {
  return db
    .prepare(
      `
    SELECT jid, name, last_message_time, channel, is_group
    FROM chats
    ORDER BY last_message_time DESC
  `,
    )
    .all() as ChatInfo[];
}

/** Correct legacy BlueBubbles `;+;` group GUIDs without touching timestamps. */
export function reconcileBlueBubblesGroupChatMetadata(): number {
  if (!isDatabaseInitialized()) return 0;
  return db
    .prepare(
      `UPDATE chats
       SET is_group = 1
       WHERE jid LIKE 'bb:%;+;%'
         AND COALESCE(is_group, 0) <> 1`,
    )
    .run().changes;
}

/**
 * Get timestamp of last group metadata sync.
 */
export function getLastGroupSync(): string | null {
  // Store sync time in a special chat entry
  const row = db
    .prepare(`SELECT last_message_time FROM chats WHERE jid = '__group_sync__'`)
    .get() as { last_message_time: string } | undefined;
  return row?.last_message_time || null;
}

/**
 * Record that group metadata was synced.
 */
export function setLastGroupSync(): void {
  const now = new Date().toISOString();
  db.prepare(
    `INSERT OR REPLACE INTO chats (jid, name, last_message_time) VALUES ('__group_sync__', '__group_sync__', ?)`,
  ).run(now);
}

type MessageMediaAttachmentRow = {
  attachment_id: string;
  chat_jid: string;
  message_id: string;
  source_channel: MessageMediaAttachment['sourceChannel'];
  kind: MessageMediaAttachment['kind'];
  mime_type: string | null;
  filename: string | null;
  size_bytes: number | null;
  source_id: string | null;
  local_path: string | null;
  thumbnail_path: string | null;
  content_hash: string | null;
  width: number | null;
  height: number | null;
  duration_ms: number | null;
  fetch_status: MessageMediaAttachment['fetchStatus'];
  analysis_status: NonNullable<MessageMediaAttachment['analysisStatus']>;
  metadata_json: string | null;
  created_at: string;
  updated_at: string;
};

function mapMessageMediaAttachmentRow(
  row: MessageMediaAttachmentRow,
): MessageMediaAttachment {
  return {
    attachmentId: row.attachment_id,
    chatJid: row.chat_jid,
    messageId: row.message_id,
    sourceChannel: row.source_channel,
    kind: row.kind,
    mimeType: row.mime_type,
    filename: row.filename,
    sizeBytes: row.size_bytes,
    sourceId: row.source_id,
    localPath: row.local_path,
    thumbnailPath: row.thumbnail_path,
    contentHash: row.content_hash,
    width: row.width,
    height: row.height,
    durationMs: row.duration_ms,
    fetchStatus: row.fetch_status,
    analysisStatus: row.analysis_status,
    metadataJson: row.metadata_json,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function upsertMessageMediaAttachment(
  record: MessageMediaAttachment,
): void {
  const now = new Date().toISOString();
  db.prepare(
    `
      INSERT INTO message_media_attachments (
        attachment_id, chat_jid, message_id, source_channel, kind, mime_type,
        filename, size_bytes, source_id, local_path, thumbnail_path,
        content_hash, width, height, duration_ms, fetch_status,
        analysis_status, metadata_json, created_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(attachment_id) DO UPDATE SET
        chat_jid = excluded.chat_jid,
        message_id = excluded.message_id,
        source_channel = excluded.source_channel,
        kind = excluded.kind,
        mime_type = excluded.mime_type,
        filename = excluded.filename,
        size_bytes = excluded.size_bytes,
        source_id = excluded.source_id,
        local_path = COALESCE(excluded.local_path, message_media_attachments.local_path),
        thumbnail_path = COALESCE(excluded.thumbnail_path, message_media_attachments.thumbnail_path),
        content_hash = COALESCE(excluded.content_hash, message_media_attachments.content_hash),
        width = COALESCE(excluded.width, message_media_attachments.width),
        height = COALESCE(excluded.height, message_media_attachments.height),
        duration_ms = COALESCE(excluded.duration_ms, message_media_attachments.duration_ms),
        fetch_status = excluded.fetch_status,
        analysis_status = excluded.analysis_status,
        metadata_json = excluded.metadata_json,
        updated_at = excluded.updated_at
    `,
  ).run(
    record.attachmentId,
    record.chatJid,
    record.messageId,
    record.sourceChannel,
    record.kind,
    record.mimeType || null,
    record.filename || null,
    record.sizeBytes ?? null,
    record.sourceId || null,
    record.localPath || null,
    record.thumbnailPath || null,
    record.contentHash || null,
    record.width ?? null,
    record.height ?? null,
    record.durationMs ?? null,
    record.fetchStatus,
    record.analysisStatus || 'not_requested',
    record.metadataJson || null,
    record.createdAt || now,
    now,
  );
}

export function upsertMessageMediaAttachments(
  records: MessageMediaAttachment[],
): void {
  if (records.length === 0) return;
  const tx = db.transaction((items: MessageMediaAttachment[]) => {
    for (const record of items) {
      upsertMessageMediaAttachment(record);
    }
  });
  tx(records);
}

export function getMessageMediaAttachment(
  attachmentId: string,
): MessageMediaAttachment | null {
  const row = db
    .prepare(
      `
        SELECT *
        FROM message_media_attachments
        WHERE attachment_id = ?
        LIMIT 1
      `,
    )
    .get(attachmentId) as MessageMediaAttachmentRow | undefined;
  return row ? mapMessageMediaAttachmentRow(row) : null;
}

export function listMessageMediaAttachments(
  params: {
    chatJid?: string;
    messageId?: string;
    attachmentIds?: string[];
    limit?: number;
  } = {},
): MessageMediaAttachment[] {
  const clauses: string[] = [];
  const args: unknown[] = [];
  if (params.chatJid) {
    clauses.push('chat_jid = ?');
    args.push(params.chatJid);
  }
  if (params.messageId) {
    clauses.push('message_id = ?');
    args.push(params.messageId);
  }
  if (params.attachmentIds && params.attachmentIds.length > 0) {
    clauses.push(
      `attachment_id IN (${params.attachmentIds.map(() => '?').join(',')})`,
    );
    args.push(...params.attachmentIds);
  }
  const where = clauses.length > 0 ? `WHERE ${clauses.join(' AND ')}` : '';
  const rows = db
    .prepare(
      `
        SELECT *
        FROM message_media_attachments
        ${where}
        ORDER BY created_at ASC
        LIMIT ?
      `,
    )
    .all(
      ...args,
      Math.max(1, params.limit ?? 100),
    ) as MessageMediaAttachmentRow[];
  return rows.map(mapMessageMediaAttachmentRow);
}

function hydrateMessagesWithMedia(messages: NewMessage[]): NewMessage[] {
  if (messages.length === 0) return messages;
  const conditions = messages.map(() => '(chat_jid = ? AND message_id = ?)');
  const args = messages.flatMap((message) => [message.chat_jid, message.id]);
  const rows = db
    .prepare(
      `
        SELECT *
        FROM message_media_attachments
        WHERE ${conditions.join(' OR ')}
        ORDER BY created_at ASC
      `,
    )
    .all(...args) as MessageMediaAttachmentRow[];
  if (rows.length === 0) return messages;
  const byMessage = new Map<string, MessageMediaAttachment[]>();
  for (const row of rows) {
    const key = `${row.chat_jid}\u0000${row.message_id}`;
    const list = byMessage.get(key) || [];
    list.push(mapMessageMediaAttachmentRow(row));
    byMessage.set(key, list);
  }
  return messages.map((message) => ({
    ...message,
    attachments:
      byMessage.get(`${message.chat_jid}\u0000${message.id}`) ||
      message.attachments ||
      [],
  }));
}

/**
 * Store a message with full content.
 * Only call this for registered groups where message history is needed.
 */
export function storeMessage(msg: NewMessage): void {
  db.prepare(
    `INSERT OR REPLACE INTO messages (id, chat_jid, sender, sender_name, content, timestamp, is_from_me, is_bot_message, thread_id, reply_to_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).run(
    msg.id,
    msg.chat_jid,
    msg.sender,
    msg.sender_name,
    msg.content,
    msg.timestamp,
    msg.is_from_me ? 1 : 0,
    msg.is_bot_message ? 1 : 0,
    msg.thread_id || null,
    msg.reply_to_id || null,
  );
  if (msg.attachments?.length) {
    upsertMessageMediaAttachments(
      msg.attachments.map((attachment) => ({
        ...attachment,
        chatJid: msg.chat_jid,
        messageId: msg.id,
      })),
    );
  }
}

export function hasStoredMessage(chatJid: string, messageId: string): boolean {
  const row = db
    .prepare(
      `
        SELECT 1
        FROM messages
        WHERE chat_jid = ? AND id = ?
        LIMIT 1
      `,
    )
    .get(chatJid, messageId) as { 1: number } | undefined;
  return Boolean(row);
}

/**
 * Store a message directly.
 */
export function storeMessageDirect(msg: {
  id: string;
  chat_jid: string;
  sender: string;
  sender_name: string;
  content: string;
  timestamp: string;
  is_from_me: boolean;
  is_bot_message?: boolean;
  thread_id?: string;
  reply_to_id?: string;
  attachments?: MessageMediaAttachment[];
}): void {
  db.prepare(
    `INSERT OR REPLACE INTO messages (id, chat_jid, sender, sender_name, content, timestamp, is_from_me, is_bot_message, thread_id, reply_to_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).run(
    msg.id,
    msg.chat_jid,
    msg.sender,
    msg.sender_name,
    msg.content,
    msg.timestamp,
    msg.is_from_me ? 1 : 0,
    msg.is_bot_message ? 1 : 0,
    msg.thread_id || null,
    msg.reply_to_id || null,
  );
  if (msg.attachments?.length) {
    upsertMessageMediaAttachments(
      msg.attachments.map((attachment) => ({
        ...attachment,
        chatJid: msg.chat_jid,
        messageId: msg.id,
      })),
    );
  }
}

export function getNewMessages(
  jids: string[],
  lastTimestamp: string,
  botPrefix: string,
  limit: number = 200,
): { messages: NewMessage[]; newTimestamp: string } {
  if (jids.length === 0) return { messages: [], newTimestamp: lastTimestamp };

  const placeholders = jids.map(() => '?').join(',');
  // Filter bot messages using both the is_bot_message flag AND the content
  // prefix as a backstop for messages written before the migration ran.
  // Subquery takes the N most recent, outer query re-sorts chronologically.
  const sql = `
    SELECT * FROM (
      SELECT id, chat_jid, sender, sender_name, content, timestamp, is_from_me, thread_id, reply_to_id
      FROM messages
      WHERE timestamp > ? AND chat_jid IN (${placeholders})
        AND is_bot_message = 0 AND content NOT LIKE ?
        AND content != '' AND content IS NOT NULL
      ORDER BY timestamp DESC
      LIMIT ?
    ) ORDER BY timestamp
  `;

  const rows = db
    .prepare(sql)
    .all(lastTimestamp, ...jids, `${botPrefix}:%`, limit) as NewMessage[];
  const hydratedRows = hydrateMessagesWithMedia(rows);

  let newTimestamp = lastTimestamp;
  for (const row of hydratedRows) {
    if (row.timestamp > newTimestamp) newTimestamp = row.timestamp;
  }

  return { messages: hydratedRows, newTimestamp };
}

export function getMessagesSince(
  chatJid: string,
  sinceTimestamp: string,
  botPrefix: string,
  limit: number = 200,
): NewMessage[] {
  // Filter bot messages using both the is_bot_message flag AND the content
  // prefix as a backstop for messages written before the migration ran.
  // Subquery takes the N most recent, outer query re-sorts chronologically.
  const sql = `
    SELECT * FROM (
      SELECT id, chat_jid, sender, sender_name, content, timestamp, is_from_me, thread_id, reply_to_id
      FROM messages
      WHERE chat_jid = ? AND timestamp > ?
        AND is_bot_message = 0 AND content NOT LIKE ?
        AND content != '' AND content IS NOT NULL
      ORDER BY timestamp DESC
      LIMIT ?
    ) ORDER BY timestamp
  `;
  const rows = db
    .prepare(sql)
    .all(chatJid, sinceTimestamp, `${botPrefix}:%`, limit) as NewMessage[];
  return hydrateMessagesWithMedia(rows);
}

export function listRecentMessagesForChat(
  chatJid: string,
  limit: number = 20,
): NewMessage[] {
  const rows = db
    .prepare(
      `
        SELECT id, chat_jid, sender, sender_name, content, timestamp, is_from_me, is_bot_message, thread_id, reply_to_id
        FROM messages
        WHERE chat_jid = ?
          AND content != '' AND content IS NOT NULL
        ORDER BY timestamp DESC
        LIMIT ?
      `,
    )
    .all(chatJid, Math.max(1, limit)) as NewMessage[];
  return hydrateMessagesWithMedia(rows);
}

export function listMessagesForChatWindow(params: {
  chatJid: string;
  startTimestamp: string;
  endTimestamp?: string | null;
  limit?: number;
}): NewMessage[] {
  const rows = db
    .prepare(
      `
        SELECT id, chat_jid, sender, sender_name, content, timestamp, is_from_me, is_bot_message, thread_id, reply_to_id
        FROM messages
        WHERE chat_jid = ?
          AND timestamp >= ?
          AND (? IS NULL OR timestamp <= ?)
          AND content != '' AND content IS NOT NULL
        ORDER BY timestamp ASC
        LIMIT ?
      `,
    )
    .all(
      params.chatJid,
      params.startTimestamp,
      params.endTimestamp || null,
      params.endTimestamp || null,
      Math.max(1, params.limit ?? 400),
    ) as NewMessage[];
  return hydrateMessagesWithMedia(rows);
}

export function getLastBotMessageTimestamp(
  chatJid: string,
  botPrefix: string,
): string | undefined {
  const row = db
    .prepare(
      `SELECT MAX(timestamp) as ts FROM messages
       WHERE chat_jid = ? AND (is_bot_message = 1 OR content LIKE ?)`,
    )
    .get(chatJid, `${botPrefix}:%`) as { ts: string | null } | undefined;
  return row?.ts ?? undefined;
}

function normalizeCursorContextThreadId(threadId?: string | null): string {
  return threadId?.trim() || '';
}

export function upsertCursorOperatorContext(record: {
  chatJid: string;
  threadId?: string | null;
  selectedLaneId?: string | null;
  selectedAgentId?: string | null;
  selectedJobsByLaneJson?: string | null;
  lastListSnapshotJson?: string | null;
  lastListMessageId?: string | null;
  dashboardMessageId?: string | null;
  updatedAt?: string;
}): void {
  const threadId = normalizeCursorContextThreadId(record.threadId);
  const existing = db
    .prepare(
      `
        SELECT *
        FROM cursor_operator_contexts
        WHERE chat_jid = ? AND thread_id = ?
      `,
    )
    .get(record.chatJid, threadId) as CursorOperatorContextRecord | undefined;

  db.prepare(
    `
      INSERT INTO cursor_operator_contexts (
        chat_jid,
        thread_id,
        selected_lane_id,
        selected_agent_id,
        selected_jobs_by_lane_json,
        last_list_snapshot_json,
        last_list_message_id,
        dashboard_message_id,
        updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(chat_jid, thread_id) DO UPDATE SET
        selected_lane_id = excluded.selected_lane_id,
        selected_agent_id = excluded.selected_agent_id,
        selected_jobs_by_lane_json = excluded.selected_jobs_by_lane_json,
        last_list_snapshot_json = excluded.last_list_snapshot_json,
        last_list_message_id = excluded.last_list_message_id,
        dashboard_message_id = excluded.dashboard_message_id,
        updated_at = excluded.updated_at
    `,
  ).run(
    record.chatJid,
    threadId,
    record.selectedLaneId === undefined
      ? existing?.selected_lane_id || null
      : record.selectedLaneId,
    record.selectedAgentId === undefined
      ? existing?.selected_agent_id || null
      : record.selectedAgentId,
    record.selectedJobsByLaneJson === undefined
      ? existing?.selected_jobs_by_lane_json || null
      : record.selectedJobsByLaneJson,
    record.lastListSnapshotJson === undefined
      ? existing?.last_list_snapshot_json || null
      : record.lastListSnapshotJson,
    record.lastListMessageId === undefined
      ? existing?.last_list_message_id || null
      : record.lastListMessageId,
    record.dashboardMessageId === undefined
      ? existing?.dashboard_message_id || null
      : record.dashboardMessageId,
    record.updatedAt || new Date().toISOString(),
  );
}

