export function consumeAlexaOAuthAuthorizationCode(
  codeHash: string,
  usedAt: string,
  now = new Date().toISOString(),
): boolean {
  const result = db
    .prepare(
      `
        UPDATE alexa_oauth_authorization_codes
        SET used_at = ?
        WHERE code_hash = ?
          AND used_at IS NULL
          AND expires_at > ?
      `,
    )
    .run(usedAt, codeHash, now);
  return result.changes === 1;
}

