export function buildCognitiveReplayPacket(params: {
  runId?: string | null;
  generatedAt: string;
  limit?: number;
}): CognitiveReplayPacket {
  const latestRun = params.runId
    ? getCognitiveRun(params.runId) || null
    : listCognitiveRuns({ runOrigin: 'live', limit: 1 })[0] || null;
  const runId = params.runId || latestRun?.runId || null;
  return {
    generatedAt: params.generatedAt,
    runId,
    latestRun,
    spans: runId
      ? listCognitiveTraceSpans({ runId, limit: params.limit || 100 })
      : [],
    simulations: runId
      ? listCognitiveToolSimulations({ runId, limit: params.limit || 100 })
      : [],
    policyDecisions: runId
      ? listCognitivePolicyDecisions({ runId, limit: params.limit || 100 })
      : [],
    toolResults: runId
      ? listCognitiveToolResults({ runId, limit: params.limit || 100 })
      : [],
    executionSteps: runId
      ? listCognitiveExecutionSteps({ runId, limit: params.limit || 100 })
      : [],
    evidenceArtifacts: runId
      ? listCognitiveEvidenceArtifacts({ runId, limit: params.limit || 100 })
      : [],
    loopStates: runId
      ? listCognitiveExecutionLoopStates({ runId, limit: params.limit || 100 })
      : [],
    stepVerifications: runId
      ? listCognitiveStepVerifications({ runId, limit: params.limit || 100 })
      : [],
    approvalPackets: runId
      ? listCognitiveApprovalPackets({ runId, limit: params.limit || 100 })
      : [],
    planRevisions: runId
      ? listCognitivePlanRevisions({ runId, limit: params.limit || 100 })
      : [],
    runEvents: runId
      ? listCognitiveRunEvents({ runId, limit: params.limit || 100 })
      : [],
    trajectoryScores: runId
      ? listCognitiveTrajectoryScores({ runId, limit: params.limit || 100 })
      : [],
    governancePolicies: listCognitiveGovernancePolicies({
      status: 'active',
      limit: 20,
    }),
    actionIdentities: runId
      ? listCognitiveActionIdentities({ runId, limit: params.limit || 100 })
      : [],
    governanceDecisions: runId
      ? listCognitiveGovernanceDecisions({ runId, limit: params.limit || 100 })
      : [],
    guardrailTripwires: runId
      ? listCognitiveGuardrailTripwires({ runId, limit: params.limit || 100 })
      : [],
    handoffs: runId
      ? listCognitiveHandoffs({ runId, limit: params.limit || 100 })
      : [],
    riskSignals: runId
      ? listCognitiveRiskSignals({ runId, limit: params.limit || 100 })
      : [],
    memoryBlocks: runId
      ? listCognitiveMemoryBlocks({ runId, limit: params.limit || 100 })
      : [],
    workbenchStates: runId
      ? listCognitiveWorkbenchStates({ runId, limit: params.limit || 100 })
      : [],
    providerCooldowns: listCognitiveProviderCooldowns({
      status: 'active',
      activeAt: params.generatedAt,
      limit: 25,
    }),
    checkpoints: runId
      ? listCognitiveCheckpoints({ runId, limit: params.limit || 50 })
      : [],
    privacy: {
      metadataOnly: true,
      rawPromptsStored: false,
      rawPrivateBodiesStored: false,
      hiddenReasoningStored: false,
      secretsRedacted: true,
    },
  };
}

