export function getAgentOSEpisode(
  episodeId: string,
): AgentOSEpisode | undefined {
  const row = db
    .prepare(
      `
        SELECT *
        FROM agent_os_episodes
        WHERE episode_id = ?
        LIMIT 1
      `,
    )
    .get(episodeId) as Parameters<typeof mapAgentOSEpisodeRow>[0] | undefined;
  return row ? mapAgentOSEpisodeRow(row) : undefined;
}

